create table if not exists public.support_tickets (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject text not null default 'Support request' check(char_length(subject) between 3 and 120),status text not null default 'open' check(status in ('open','closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_message_at timestamptz not null default now());
create table if not exists public.support_messages (id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets(id) on delete cascade,sender_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(trim(body)) between 1 and 4000),created_at timestamptz not null default now(),read_at timestamptz);
create index if not exists support_tickets_user_last_idx on public.support_tickets(user_id,last_message_at desc);
create index if not exists support_messages_ticket_created_idx on public.support_messages(ticket_id,created_at);
alter table public.support_tickets enable row level security; alter table public.support_messages enable row level security;
grant select,insert,update on public.support_tickets to authenticated; grant select,insert,update on public.support_messages to authenticated;
create policy "Users and admins read support tickets" on public.support_tickets for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
create policy "Users create own support tickets" on public.support_tickets for insert to authenticated with check(user_id=(select auth.uid()));
create policy "Users update own support ticket activity" on public.support_tickets for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
revoke update on public.support_tickets from authenticated; grant update(last_message_at,updated_at) on public.support_tickets to authenticated;
create policy "Admins update support tickets" on public.support_tickets for update to authenticated using(exists(select 1 from public.admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
create policy "Ticket owners and admins read support messages" on public.support_messages for select to authenticated using(exists(select 1 from public.support_tickets t where t.id=ticket_id and (t.user_id=(select auth.uid()) or exists(select 1 from public.admins a where a.user_id=(select auth.uid())))));
create policy "Ticket participants send support messages" on public.support_messages for insert to authenticated with check(sender_id=(select auth.uid()) and exists(select 1 from public.support_tickets t where t.id=ticket_id and (t.user_id=(select auth.uid()) or exists(select 1 from public.admins a where a.user_id=(select auth.uid()))) and t.status='open'));
create policy "Recipients mark support messages read" on public.support_messages for update to authenticated using(sender_id<>(select auth.uid()) and exists(select 1 from public.support_tickets t where t.id=ticket_id and (t.user_id=(select auth.uid()) or exists(select 1 from public.admins a where a.user_id=(select auth.uid()))))) with check(sender_id<>(select auth.uid()) and exists(select 1 from public.support_tickets t where t.id=ticket_id and (t.user_id=(select auth.uid()) or exists(select 1 from public.admins a where a.user_id=(select auth.uid())))));
create or replace function public.souki_touch_support_ticket() returns trigger language plpgsql set search_path=public as $$ begin update public.support_tickets set last_message_at=new.created_at,updated_at=now() where id=new.ticket_id; return new; end; $$;
create trigger souki_support_message_touch after insert on public.support_messages for each row execute function public.souki_touch_support_ticket();
alter publication supabase_realtime add table public.support_messages;